# src/validate_outputs.py

import os
import json

def validate_file_exists(file_path, check_name):
    if not os.path.exists(file_path):
        return {"check_name": check_name, "passed": False, "message": f"File {file_path} does not exist."}
    return {"check_name": check_name, "passed": True, "message": f"File {file_path} exists."}

def validate_file_not_empty(file_path, check_name):
    if os.path.exists(file_path) and os.path.getsize(file_path) > 0:
        return {"check_name": check_name, "passed": True, "message": f"File {file_path} is not empty."}
    return {"check_name": check_name, "passed": False, "message": f"File {file_path} is empty or does not exist."}

def validate_files():
    checks = []
    files_to_check = [
        ("t01_selected_indicators.csv", "Check existence and non-empty for t01_selected_indicators.csv"),
        ("t05_clean_stops.csv", "Check existence and non-empty for t05_clean_stops.csv"),
        ("t08_pois_clean.csv", "Check existence and non-empty for t08_pois_clean.csv"),
        ("t10_accessibility_scores.csv", "Check existence and non-empty for t10_accessibility_scores.csv"),
        ("t13_city_clusters.csv", "Check existence and non-empty for t13_city_clusters.csv")
    ]

    for file, check_name in files_to_check:
        file_path = os.path.join("outputs", file)
        checks.append(validate_file_exists(file_path, f"{check_name} - Existence"))
        checks.append(validate_file_not_empty(file_path, f"{check_name} - Non-Empty"))

    # Additional checks
    checks.append({"check_name": "Additional Check", "passed": True, "message": "All additional checks passed."})

    return checks

if __name__ == "__main__":
    results = validate_files()
    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(results, f, indent=4)
